298 class D3D11ZoneScope
299 {
300 public:
301     tracy_force_inline D3D11ZoneScope( D3D11Ctx* ctx, const SourceLocationData* srcloc, bool active )
302         : D3D11ZoneScope(ctx, active)
303     {
304         if( !m_active ) return;
305 
306         auto* item = Profiler::QueueSerial();
307         WriteQueueItem(item, QueueType::GpuZoneBeginSerial, reinterpret_cast<uint64_t>(srcloc));
308     }
309 
310     tracy_force_inline D3D11ZoneScope( D3D11Ctx* ctx, const SourceLocationData* srcloc, int depth, bool active )
311         : D3D11ZoneScope(ctx, active)
312     {
313         if( !m_active ) return;
314 
315         auto* item = Profiler::QueueSerialCallstack(Callstack(depth));
316         WriteQueueItem(item, QueueType::GpuZoneBeginCallstackSerial, reinterpret_cast<uint64_t>(srcloc));
317     }
318 
319     tracy_force_inline D3D11ZoneScope(D3D11Ctx* ctx, uint32_t line, const char* source, size_t sourceSz, const char* function, size_t functionSz, const char* name, size_t nameSz, bool active)
320         : D3D11ZoneScope(ctx, active)
321     {
322         if( !m_active ) return;
323 
324         const auto sourceLocation = Profiler::AllocSourceLocation(line, source, sourceSz, function, functionSz, name, nameSz);
325 
326         auto* item = Profiler::QueueSerial();
327         WriteQueueItem(item, QueueType::GpuZoneBeginAllocSrcLocSerial, sourceLocation);
328     }
329 
330     tracy_force_inline D3D11ZoneScope(D3D11Ctx* ctx, uint32_t line, const char* source, size_t sourceSz, const char* function, size_t functionSz, const char* name, size_t nameSz, int depth, bool active)
331         : D3D11ZoneScope(ctx, active)
332     {
333         if( !m_active ) return;
334 
335         const auto sourceLocation = Profiler::AllocSourceLocation(line, source, sourceSz, function, functionSz, name, nameSz);
336 
337         auto* item = Profiler::QueueSerialCallstack(Callstack(depth));
338         WriteQueueItem(item, QueueType::GpuZoneBeginAllocSrcLocCallstackSerial, sourceLocation);
339     }
340 
341     tracy_force_inline ~D3D11ZoneScope()
342     {
343         if( !m_active ) return;
344 
345         const auto queryId = m_ctx->NextQueryId();
346         m_ctx->m_immediateDevCtx->End(m_ctx->GetQueryObjectFromId(queryId));
347 
348         auto* item = Profiler::QueueSerial();
349         MemWrite( &item->hdr.type, QueueType::GpuZoneEndSerial );
350         MemWrite( &item->gpuZoneEnd.cpuTime, Profiler::GetTime() );
351         MemWrite( &item->gpuZoneEnd.thread, GetThreadHandle() );
352         MemWrite( &item->gpuZoneEnd.queryId, uint16_t( queryId ) );
353         MemWrite( &item->gpuZoneEnd.context, m_ctx->GetContextId() );
354         Profiler::QueueSerialFinish();
355     }
356 
357 private:
358     tracy_force_inline D3D11ZoneScope( D3D11Ctx* ctx, bool active )
359 #ifdef TRACY_ON_DEMAND
360         : m_active( is_active && GetProfiler().IsConnected() )
361 #else
362         : m_active( active )
363 #endif
364     {
365         if( !m_active ) return;
366         m_ctx = ctx;
367     }
368 
369     void WriteQueueItem(tracy::QueueItem* item, tracy::QueueType queueItemType, uint64_t sourceLocation)
370     {
371         const auto queryId = m_ctx->NextQueryId();
372         m_ctx->m_immediateDevCtx->End(m_ctx->GetQueryObjectFromId(queryId));
373 
374         MemWrite( &item->hdr.type, queueItemType);
375         MemWrite( &item->gpuZoneBegin.cpuTime, Profiler::GetTime() );
376         MemWrite( &item->gpuZoneBegin.srcloc, sourceLocation );
377         MemWrite( &item->gpuZoneBegin.thread, GetThreadHandle() );
378         MemWrite( &item->gpuZoneBegin.queryId, uint16_t( queryId ) );
379         MemWrite( &item->gpuZoneBegin.context, m_ctx->GetContextId() );
380         Profiler::QueueSerialFinish();
381     }
382 
383     const bool m_active;
384 
385     D3D11Ctx* m_ctx;
386 };
387 
388 static inline D3D11Ctx* CreateD3D11Context( ID3D11Device* device, ID3D11DeviceContext* devicectx )
389 {
390     auto ctx = (D3D11Ctx*)tracy_malloc( sizeof( D3D11Ctx ) );
391     new(ctx) D3D11Ctx( device, devicectx );
392     return ctx;
393 }
394 
395 static inline void DestroyD3D11Context( D3D11Ctx* ctx )
396 {
397     ctx->~D3D11Ctx();
398     tracy_free( ctx );
399 }
400 }
